        <div class="field-row adv">
          <label class="field grow">
            <span>Icon URL</span>
            <input id="f_icon" type="text" />
          </label>
          <label class="field grow">
            <span>Preview image URL</span>
            <input id="f_preview_image" type="text" />
          </label>
        </div>
        <div id="snapSection" class="snap-section hidden">
          <div class="side-head">
            <span>Snapshots</span>
            <button id="snapBtn" class="btn" type="button">Capture snapshot</button>
          </div>
          <div id="snapList" class="snap-list"></div>
        </div>
      </div>
      <div class="modal-foot">
        <button id="deleteBtn" class="btn btn-danger hidden" type="button">Delete</button>
        <span class="spacer"></span>
        <button class="btn btn-ghost" data-close type="button">Cancel</button>
        <button id="saveBtn" class="btn btn-primary" type="button">Save</button>
      </div>
    </div>
  </div>

  <!-- Preferences modal -->
  <div id="prefsModal" class="modal hidden">
    <div class="modal-card small">
      <div class="modal-head"><h2>Preferences</h2><button class="icon-btn" data-close>✕</button></div>
      <div class="modal-body">
        <label class="field">
          <span>Default sort</span>
          <select id="p_sort">
            <option value="created_desc">Newest first</option>
            <option value="created_asc">Oldest first</option>
            <option value="updated_desc">Recently updated</option>
            <option value="title_asc">Title A→Z</option>
            <option value="title_desc">Title Z→A</option>
            <option value="domain_asc">Site A→Z</option>
          </select>
        </label>
        <label class="field">
          <span>Default view</span>
          <select id="p_view">
            <option value="all">All</option>
            <option value="read_later">Read later</option>
            <option value="archived">Archived</option>
          </select>
        </label>
        <label class="field">
          <span>Font size</span>
          <select id="p_font">
            <option value="small">Small</option>
            <option value="medium">Medium</option>
            <option value="large">Large</option>
          </select>
        </label>
      </div>
      <div class="modal-foot">
        <span class="spacer"></span>
        <button class="btn btn-ghost" data-close>Cancel</button>
        <button id="savePrefsBtn" class="btn btn-primary">Save</button>
      </div>
    </div>
  </div>

  <!-- Import/Export modal -->
  <div id="ioModal" class="modal hidden">
    <div class="modal-card small">
      <div class="modal-head"><h2>Import / Export</h2><button class="icon-btn" data-close>✕</button></div>
      <div class="modal-body">
        <div class="io-block">
          <h3>Export</h3>
          <div class="field-row">
            <a class="btn" href="/api/export?format=json">Download JSON</a>
            <a class="btn" href="/api/export?format=html">Download HTML</a>
          </div>
        </div>
        <div class="io-block">
          <h3>Import</h3>
          <p class="hint">Accepts this app's JSON export or a browser's exported bookmarks HTML. Duplicate URLs are skipped.</p>
          <input id="importFile" type="file" accept=".json,.html,.htm,application/json,text/html" />
          <div id="importResult" class="hint"></div>
        </div>
      </div>
      <div class="modal-foot">
        <span class="spacer"></span>
        <button class="btn btn-ghost" data-close>Close</button>
      </div>
    </div>
  </div>

  <!-- Snapshot viewer -->
  <div id="snapViewer" class="modal hidden">
    <div class="modal-card wide">
      <div class="modal-head"><h2 id="snapViewerTitle">Snapshot</h2><button class="icon-btn" data-close>✕</button></div>
      <div class="modal-body snap-viewer-body">
        <img id="snapViewerImg" alt="snapshot" />
      </div>
      <div class="modal-foot">
        <a id="snapViewerHtml" class="btn" target="_blank" rel="noopener">Open saved HTML</a>
        <span class="spacer"></span>
        <button class="btn btn-ghost" data-close>Close</button>
      </div>
    </div>
  </div>

  <div id="toast" class="toast hidden"></div>

  <!-- prompt modal for tag input on bulk -->
  <script src="/app.js"></script>
</body>
</html>

